#include "nvfs_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void nvfs_wr_entry (NVFS_Entry * const nvfs_entry , UInt16 entry_addr)
{
  nvfs_range_check (entry_addr                         ) ;
  nvfs_range_check (entry_addr + sizeof *nvfs_entry - 1) ;

  nvfs_crc_calc_entry_link (& nvfs_entry->link.name) ;
  nvfs_crc_calc_entry_link (& nvfs_entry->link.data) ;

  nvfs_crc_calc_entry (nvfs_entry) ;

  if (!nvram_wr (entry_addr , nvfs_entry , sizeof *nvfs_entry))
    {
      NvfsThrow NVFS_ERROR ;
    }
}

